/* Token Radar. Dark slate canvas, warm amber accent, teal secondary. An 8px spacing scale, tabular
   figures and one type family; every colour, radius and step is a token so the page stays consistent. */
:root {
  --canvas: #0f1720;
  --surface: #16202b;
  --surface-2: #1d2936;
  --surface-3: #243342;
  --ink: #e8eef4;
  --muted: #93a4b5;
  --faint: #6b7c8d;
  --border: #2a3a49;
  --border-soft: #21303d;
  --amber: #f0b429;
  --amber-dim: #b9861a;
  --teal: #3fb8a0;
  --negative: #e2705f;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-num: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, monospace;
  --s1: 8px;
  --s2: 16px;
  --s3: 24px;
  --s4: 32px;
  --s5: 48px;
  --s6: 64px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; font-weight: 600; }
h1 { font-size: 32px; line-height: 1.12; }
h2 { font-size: 20px; line-height: 1.25; }
h3 { font-size: 15px; line-height: 1.3; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.sub { color: var(--muted); font-size: 13px; }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--s1) var(--s2);
  background: var(--surface); border: 1px solid var(--border); z-index: 50; color: var(--ink);
}
.skip:focus { left: var(--s2); top: var(--s2); }
:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }

.shell { max-width: 1360px; margin: 0 auto; padding: var(--s3) var(--s4) var(--s6); }

/* ---- top bar ---- */
.top {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s3);
  padding-bottom: var(--s2); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--s1); }
.mark {
  width: 14px; height: 14px; border-radius: 3px; flex: none;
  background: linear-gradient(135deg, var(--amber) 0 50%, var(--teal) 50% 100%);
}
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--s2); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.top-meta b { color: var(--ink); font-weight: 500; }

/* ---- hero ---- */
.hero { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.85fr); gap: var(--s4); padding: var(--s4) 0 var(--s3); align-items: start; }
.hero h1 { max-width: 20ch; }
.hero h1 em { color: var(--amber); font-style: normal; }
.lede { color: var(--muted); max-width: 64ch; margin-top: var(--s2); }
.lede strong { color: var(--ink); font-weight: 500; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--border-soft); border: 1px solid var(--border-soft); border-radius: var(--radius); overflow: hidden; }
.fact { background: var(--surface); padding: var(--s2); display: grid; gap: 4px; }
.fact b { font-family: var(--font-num); font-size: 24px; font-weight: 600; color: var(--ink); line-height: 1; }
.fact b.amber { color: var(--amber); }
.fact b.teal { color: var(--teal); }
.fact span { color: var(--muted); font-size: 12px; }

/* ---- model section ---- */
.model { margin: var(--s2) 0 var(--s3); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: var(--s3); }
.model-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: var(--s1); margin-bottom: var(--s1); }
.model h2 { color: var(--amber); }
.model p { color: var(--muted); max-width: 90ch; }
.model p strong { color: var(--ink); font-weight: 500; }
.formula {
  margin: var(--s2) 0; padding: var(--s2); border-radius: var(--radius); background: #0b1219;
  border: 1px solid var(--border-soft); font-family: var(--font-num); font-size: 12.5px; line-height: 1.75;
  color: var(--teal); overflow-wrap: anywhere; white-space: pre-wrap;
}
.formula .k { color: var(--amber); }
.peer-wrap { margin-top: var(--s2); }
.peer-wrap h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin-bottom: var(--s1); font-weight: 500; }
.peer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 1px; background: var(--border-soft); border: 1px solid var(--border-soft); border-radius: var(--radius); overflow: hidden; }
.peer {
  background: var(--surface-2); padding: var(--s1) 12px; display: flex; align-items: baseline;
  justify-content: space-between; gap: var(--s1); font-size: 12.5px;
}
.peer .cat { color: var(--ink); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.peer .mult { font-family: var(--font-num); color: var(--amber); font-weight: 600; white-space: nowrap; }
.peer .cnt { color: var(--faint); font-family: var(--font-num); font-size: 11px; }
.peer.fallback { background: #131d26; }
.peer.fallback .mult { color: var(--teal); }
.peer.fallback .cat { color: var(--muted); }

/* ---- held-out cross-validation block ---- */
.cv { margin: var(--s2) 0; padding: var(--s2); border: 1px solid var(--border-soft); border-radius: var(--radius); background: #0b1219; }
.cv-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: var(--s1); margin-bottom: var(--s1); }
.cv-head h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); font-weight: 500; }
.cv-grid { display: grid; gap: 1px; background: var(--border-soft); border: 1px solid var(--border-soft); border-radius: var(--radius-sm); overflow: hidden; }
.cv-row { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s2); padding: var(--s1) 12px; background: var(--surface-2); font-size: 12.5px; }
.cv-row .cv-k { color: var(--muted); }
.cv-row .cv-v { font-family: var(--font-num); color: var(--ink); font-weight: 600; white-space: nowrap; }
.cv-row.best { background: color-mix(in srgb, var(--teal) 14%, var(--surface-2)); }
.cv-row.best .cv-k { color: var(--ink); }
.cv-row.best .cv-v { color: var(--teal); }

/* ---- controls ---- */
.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--s2); padding: var(--s2) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: 6px; }
.field label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.field input, .field select {
  min-height: 38px; padding: 0 12px; border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--surface); min-width: 180px; color: var(--ink);
}
.field input { min-width: 260px; }
.field input::placeholder { color: var(--faint); }
.seg { display: flex; gap: 2px; padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface); }
.seg button { min-height: 30px; padding: 0 12px; border: 0; border-radius: 5px; background: transparent; color: var(--muted); font-size: 13px; white-space: nowrap; }
.seg button:hover { color: var(--ink); }
.seg button[aria-pressed="true"] { background: var(--amber); color: #1a1200; font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }
.count b { color: var(--amber); font-family: var(--font-num); }

/* ---- table ---- */
.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--s2) var(--s2) var(--s1); color: var(--muted); font-size: 13px; }
th, td { padding: 5px var(--s2); line-height: 1.35; border-bottom: 1px solid var(--border-soft); text-align: left; vertical-align: middle; }
thead th { position: sticky; top: 0; background: var(--surface-2); z-index: 2; }
th { color: var(--muted); font-size: 11px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: 4px; border: 0; background: none; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
th button:hover { color: var(--ink); }
th button .arrow { color: var(--amber); font-size: 10px; }
th[aria-sort] button { color: var(--ink); }
tbody tr { cursor: pointer; transition: background 120ms ease; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: color-mix(in srgb, var(--amber) 10%, var(--surface)); box-shadow: inset 3px 0 0 var(--amber); }
tbody tr:last-child td { border-bottom: 0; }
/* Keyboard focus on tbody rows and every button reads in the amber accent, inset so the table's
   overflow wrapper never clips it. */
