.bar { width: 70px; height: 6px; border-radius: 3px; background: var(--surface-3); overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--amber-dim), var(--amber)); }
.range { font-family: var(--font-num); font-size: 11px; color: var(--faint); white-space: nowrap; }
.pill { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-family: var(--font-num); white-space: nowrap; }
.pill.cat { background: var(--surface-3); color: var(--ink); }
.pill.glb { background: color-mix(in srgb, var(--teal) 18%, var(--surface)); color: var(--teal); }
.pill.buy { background: color-mix(in srgb, var(--amber) 16%, var(--surface)); color: var(--amber); }
.board-footnote { padding: 10px var(--s2) 12px; color: var(--faint); font-size: 12px; border-top: 1px solid var(--border-soft); }

.empty { padding: var(--s5) var(--s3); text-align: center; display: grid; gap: var(--s2); justify-items: center; }
.empty p { color: var(--muted); max-width: 44ch; }
.button { min-height: 38px; padding: 0 var(--s2); border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface-2); color: var(--ink); }
.button.primary { background: var(--amber); border-color: var(--amber); color: #1a1200; font-weight: 600; }

/* ---- detail drawer ---- */
.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 20;
  background: var(--surface); border-left: 1px solid var(--border); padding: var(--s3);
  overflow-y: auto; box-shadow: -24px 0 60px rgba(0, 0, 0, 0.45); margin: 0 0 0 auto; max-height: 100%;
}
.detail::backdrop { background: rgba(5, 9, 13, 0.62); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s2); }
.detail-head > div { min-width: 0; }
.detail-head h2 { margin-top: 4px; font-size: 24px; }
.detail-head .sub { overflow-wrap: anywhere; margin-top: 4px; }
.close { flex: none; min-height: 34px; padding: 0 12px; white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface-2); color: var(--ink); }
.detail-section { margin-top: var(--s3); padding-top: var(--s2); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s1); color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.hero-value { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--s1); }
.hero-value .big { font-family: var(--font-num); font-size: 34px; font-weight: 700; color: var(--amber); line-height: 1; }
.hero-value .rng { font-family: var(--font-num); font-size: 13px; color: var(--muted); }
.equation { display: grid; gap: 0; margin-top: var(--s1); }
.equation div { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s2); padding: 7px 0; border-bottom: 1px dashed var(--border-soft); }
.equation div:last-child { border-bottom: 0; }
.equation span { color: var(--muted); }
.equation span small { color: var(--faint); }
.equation b { font-family: var(--font-num); font-weight: 500; color: var(--ink); text-align: right; }
.equation b.hl { color: var(--amber); }
.note { margin-top: var(--s1); color: var(--faint); font-size: 12px; line-height: 1.5; }
.steps { margin: 0; padding: 0; list-style: none; display: grid; gap: var(--s2); counter-reset: step; }
.steps li { position: relative; padding-left: 34px; counter-increment: step; }
.steps li::before {
  content: counter(step); position: absolute; left: 0; top: 0; width: 24px; height: 24px;
  display: grid; place-items: center; border-radius: 50%; background: var(--surface-3);
  color: var(--amber); font-family: var(--font-num); font-size: 12px; font-weight: 600;
}
.steps b { display: block; font-weight: 500; color: var(--ink); }
.cost { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.cost span { font-family: var(--font-num); font-size: 11px; padding: 2px 8px; border-radius: 999px; background: var(--surface-3); color: var(--teal); }
.cost span.time { color: var(--amber); }

@media (max-width: 980px) {
  .shell { padding: var(--s2) var(--s2) var(--s5); }
  .hero { grid-template-columns: 1fr; gap: var(--s3); }
  .field input { min-width: 0; width: 100%; }
  .field { flex: 1 1 100%; }
  .count { margin-left: 0; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
